    justify-content: center;
    color: #949ba4;
}

/* Message Bubble */
::deep .message-bubble {
    padding: 8px 12px;
    border-radius: 4px;
    position: relative;
}

::deep .message-bubble:hover {
    background: #2e3035;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

::deep .message-author {
    font-weight: 600;
    font-size: 0.9rem;
}

::deep .message-time {
    font-size: 0.7rem;
    color: #949ba4;
}

::deep .message-content {
    margin-top: 4px;
    font-size: 0.9rem;
    line-height: 1.4;
    word-break: break-word;
}

::deep .message-reactions {
    display: flex;
    gap: 4px;
    margin-top: 6px;
    flex-wrap: wrap;
}

::deep .reaction-badge {
    background: #3f4147;
    border: 1px solid #4e5058;
    border-radius: 4px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    color: #f2f3f5;
}

::deep .reaction-badge:hover {
    border-color: #5865f2;
}

::deep .thread-link {
    background: none;
    border: none;
    color: #00a8fc;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 4px 0;
    margin-top: 4px;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

/* Message Actions */
::deep .message-actions {
    position: absolute;
    top: -12px;
    right: 12px;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    display: flex;
    gap: 2px;
    padding: 2px;
}

::deep .action-btn {
    background: none;
    border: none;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 3px;
    font-size: 0.9rem;
}

::deep .action-btn:hover {
    background: #3f4147;
}

/* Emoji Picker */
::deep .emoji-picker {
    position: absolute;
    top: -44px;
    right: 12px;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 6px;
    padding: 6px;
    display: flex;
    gap: 4px;
    z-index: 10;
}

::deep .emoji-option {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1.2rem;
    padding: 4px;
    border-radius: 4px;
}

::deep .emoji-option:hover {
    background: #3f4147;
}

/* Message Input */
::deep .message-input-area {
    padding: 12px 16px;
    display: flex;
    gap: 8px;
    align-items: flex-end;
    border-top: 1px solid #3f4147;
}

::deep .message-textarea {
    flex: 1;
    background: #383a40;
    border: none;
    border-radius: 8px;
    padding: 10px 14px;
    color: #f2f3f5;
    font-size: 0.9rem;
    resize: none;
    outline: none;
    font-family: inherit;
}

::deep .message-textarea:focus {
    box-shadow: 0 0 0 2px #5865f2;
}

::deep .send-btn {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 10px 18px;
    font-weight: 600;
    cursor: pointer;
    font-size: 0.85rem;
}

::deep .send-btn:hover {
    background: #4752c4;
}

::deep .send-btn:disabled {
    background: #4e5058;
    cursor: not-allowed;
}

/* Thread Panel */
.chat-layout.thread-open ::deep .message-area {
    flex: 0 0 55%;
}

::deep .thread-panel {
    width: 25%;
    min-width: 280px;
    background: #2b2d31;
    color: #f2f3f5;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #1e1f22;
}

::deep .thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
}

::deep .thread-header h3 {
    margin: 0;
    font-size: 1rem;
}

::deep .close-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

::deep .close-btn:hover {
    background: #3f4147;
    color: #f2f3f5;
}

::deep .thread-root-message {
    padding: 12px 16px;
    background: #1e1f22;
    margin: 12px;
    border-radius: 6px;
    border-left: 3px solid #5865f2;
}

::deep .thread-root-message .message-author {
    font-weight: 600;
    font-size: 0.85rem;
}

::deep .thread-root-message .message-content {
    margin-top: 4px;
    font-size: 0.85rem;
    color: #b5bac1;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 16px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

::deep .thread-reply {
    padding: 8px 0;
}

::deep .thread-reply .message-content {
    font-size: 0.85rem;
}
"}

