+@page "/chat"
+@namespace sv_a9ec4d5c2fb948a6bef1c4fefe9615a2.Components.Pages.Chat
+@rendermode InteractiveServer
+@inject IChatService ChatService
+
+<PageTitle>Chat</PageTitle>
+
+<div class="chat-layout @(isThreadOpen ? "thread-open" : "")">
+    <ChannelSidebar Channels="channels"
+                    ActiveChannelId="selectedChannel?.Id"
+                    OnChannelSelected="SelectChannel" />
+
+    <MessageArea Channel="selectedChannel"
+                 Messages="messages"
+                 ThreadSummaries="threadSummaries"
+                 IsLoadingMore="isLoadingMore"
+                 OnOpenThread="OpenThread"
+                 OnReact="HandleReaction"
+                 OnSendMessage="SendMessage"
+                 OnLoadOlderMessages="LoadOlderMessages" />
+
+    @if (isThreadOpen)
+    {
+        <ThreadPanel RootMessage="threadRootMessage"
+                     Replies="threadReplies"
+                     OnClose="CloseThread"
+                     OnSendReply="SendThreadReply" />
+    }
+</div>
+
+@code {
+    private List<Channel> channels = new();
+    private Channel? selectedChannel;
+    private List<Message> messages = new();
+    private List<ThreadSummary> threadSummaries = new();
+    private bool isLoadingMore;
+    private int messageSkip;
+    private const int PageSize = 30;
+
+    // Thread state
+    private bool isThreadOpen;
+    private Message? threadRootMessage;
+    private List<Message> threadReplies = new();
+
+    protected override async Task OnInitializedAsync()
+    {
+        channels = await ChatService.GetChannelsAsync();
+        if (channels.Count > 0)
+        {
+            await SelectChannel(channels[0]);
+        }
+    }
+
+    private async Task SelectChannel(Channel channel)
+    {
+        selectedChannel = channel;
+        messageSkip = 0;
+        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
+        messageSkip = messages.Count;
+        await ChatService.MarkChannelReadAsync(channel.Id);
+
+        // Compute thread summaries from messages that have replies
+        threadSummaries = messages
+            .Where(m => m.ReplyToId is null)
+            .Select(m => new { RootId = m.Id, Replies = messages.Where(r => r.ReplyToId == m.Id).ToList() })
+            .Where(x => x.Replies.Count > 0)
+            .Select(x => new ThreadSummary(x.RootId, x.Replies.Count, x.Replies.Max(r => r.SentAt)))
+            .ToList();
+
+        // Update unread count in local state
+        channels = channels.Select(c => c.Id == channel.Id ? c with { UnreadCount = 0 } : c).ToList();
+
+        CloseThread();
+    }
+
+    private async Task LoadOlderMessages()
+    {
+        if (isLoadingMore || selectedChannel is null) return;
+        isLoadingMore = true;
+        StateHasChanged();
+
+        var olderMessages = await ChatService.GetMessagesAsync(selectedChannel.Id, messageSkip, PageSize);
+        if (olderMessages.Count > 0)
+        {
+            messages = olderMessages.Concat(messages).ToList();
+            messageSkip += olderMessages.Count;
+        }
+        isLoadingMore = false;
+    }
+
+    private async Task SendMessage(string content)
+    {
+        if (selectedChannel is null) return;
+        var newMessage = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
+        messages = messages.Append(newMessage).ToList();
+    }
+
+    private async Task OpenThread(Message rootMessage)
+    {
+        threadRootMessage = rootMessage;
+        threadReplies = await ChatService.GetThreadAsync(rootMessage.Id);
+        isThreadOpen = true;
+    }
+
+    private void CloseThread()
+    {
+        isThreadOpen = false;
+        threadRootMessage = null;
+        threadReplies = new();
+    }
+
+    private async Task SendThreadReply(string content)
+    {
+        if (threadRootMessage is null || selectedChannel is null) return;
+        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, threadRootMessage.Id);
+        threadReplies = threadReplies.Append(reply).ToList();
+        messages = messages.Append(reply).ToList();
+
+        // Update thread summary
+        var existing = threadSummaries.FirstOrDefault(t => t.RootMessageId == threadRootMessage.Id);
+        if (existing is not null)
+        {
+            threadSummaries = threadSummaries
+                .Select(t => t.RootMessageId == threadRootMessage.Id
+                    ? new ThreadSummary(t.RootMessageId, t.ReplyCount + 1, reply.SentAt)
+                    : t)
+                .ToList();
+        }
+        else
+        {
+            threadSummaries = threadSummaries.Append(new ThreadSummary(threadRootMessage.Id, 1, reply.SentAt)).ToList();
+        }
+    }
+
+    private async Task HandleReaction((int MessageId, string Emoji) args)
+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+
+        // Optimistically update the local message reactions
+        messages = messages.Select(m =>
+        {
+            if (m.Id != args.MessageId) return m;
+            var reactions = m.Reactions.ToList();
+            var existing = reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
+            if (existing is not null)
+            {
+                reactions = reactions.Select(r => r.Emoji == args.Emoji
+                    ? new Reaction(r.Emoji, r.Users.Append("You").ToList())
+                    : r).ToList();
+            }
+            else
+            {
+                reactions.Add(new Reaction(args.Emoji, new List<string> { "You" }));
+            }
+            return m with { Reactions = reactions };
+        }).ToList();
+    }
+}
+

toolArgs.file_text:
/* Layout */
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

/* Sidebar */
::deep .channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2b2d31;
    color: #f2f3f5;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #1e1f22;
}

::deep .sidebar-title {
    padding: 16px;
    margin: 0;
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #b5bac1;
}

::deep .channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 0 8px;
}

::deep .channel-item {
    padding: 8px 12px;
    border-radius: 4px;
    cursor: pointer;
    margin-bottom: 2px;
    position: relative;
}

::deep .channel-item:hover {
    background: #35373c;
}

::deep .channel-item.active {
    background: #404249;
}

::deep .channel-name {
    font-weight: 600;
    font-size: 0.95rem;
}

::deep .channel-description {
    font-size: 0.75rem;
    color: #949ba4;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #f23f43;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Message Area */
::deep .message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #313338;
    color: #f2f3f5;
    min-width: 0;
}

::deep .message-area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
}

::deep .message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
}

::deep .message-area-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #949ba4;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

::deep .loading-indicator {
    text-align: center;
    color: #949ba4;
    padding: 8px;
    font-size: 0.85rem;
}

::deep .no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #949ba4;
}

/* Message Bubble */
::deep .message-bubble {
    padding: 8px 12px;
    border-radius: 4px;
    position: relative;
}

::deep .message-bubble:hover {
    background: #2e3035;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

::deep .message-author {
    font-weight: 600;
    font-size: 0.9rem;
}

::deep .message-time {
    font-size: 0.7rem;
    color: #949ba4;
}

::deep .message-content {
    margin-top: 4px;
    font-size: 0.9rem;
    line-height: 1.4;
    word-break: break-word;
}

::deep .message-reactions {
    display: flex;
    gap: 4px;
    margin-top: 6px;
    flex-wrap: wrap;
}

::deep .reaction-badge {
    background: #3f4147;
    border: 1px solid #4e5058;
    border-radius: 4px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    color: #f2f3f5;
}

::deep .reaction-badge:hover {
    border-color: #5865f2;
}

::deep .thread-link {
    background: none;
    border: none;
    color: #00a8fc;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 4px 0;
    margin-top: 4px;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

/* Message Actions */
::deep .message-actions {
    position: absolute;
    top: -12px;
    right: 12px;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    display: flex;
    gap: 2px;
    padding: 2px;
}

::deep .action-btn {
    background: none;
    border: none;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 3px;
    font-size: 0.9rem;
}

::deep .action-btn:hover {
    background: #3f4147;
}

/* Emoji Picker */
::deep .emoji-picker {
    position: absolute;
    top: -44px;
    right: 12px;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 6px;
    padding: 6px;
    display: flex;
    gap: 4px;
    z-index: 10;
}

::deep .emoji-option {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1.2rem;
    padding: 4px;
    border-radius: 4px;
}

::deep .emoji-option:hover {
    background: #3f4147;
}

/* Message Input */
::deep .message-input-area {
    padding: 12px 16px;
    display: flex;
    gap: 8px;
    align-items: flex-end;
    border-top: 1px solid #3f4147;
}

::deep .message-textarea {
    flex: 1;
    background: #383a40;
    border: none;
    border-radius: 8px;
    padding: 10px 14px;
    color: #f2f3f5;
    font-size: 0.9rem;
    resize: none;
    outline: none;
    font-family: inherit;
}

::deep .message-textarea:focus {
    box-shadow: 0 0 0 2px #5865f2;
}

::deep .send-btn {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 10px 18px;
    font-weight: 600;
    cursor: pointer;
    font-size: 0.85rem;
}

::deep .send-btn:hover {
    background: #4752c4;
}

::deep .send-btn:disabled {
    background: #4e5058;
    cursor: not-allowed;
}

/* Thread Panel */
.chat-layout.thread-open ::deep .message-area {
    flex: 0 0 55%;
}

::deep .thread-panel {
    width: 25%;
    min-width: 280px;
    background: #2b2d31;
    color: #f2f3f5;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #1e1f22;
}

::deep .thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
}

::deep .thread-header h3 {
    margin: 0;
    font-size: 1rem;
}

::deep .close-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

::deep .close-btn:hover {
    background: #3f4147;
    color: #f2f3f5;
}

::deep .thread-root-message {
    padding: 12px 16px;
    background: #1e1f22;
    margin: 12px;
    border-radius: 6px;
    border-left: 3px solid #5865f2;
}

::deep .thread-root-message .message-author {
    font-weight: 600;
    font-size: 0.85rem;
}

::deep .thread-root-message .message-content {
    margin-top: 4px;
    font-size: 0.85rem;
    color: #b5bac1;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 16px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

::deep .thread-reply {
    padding: 8px 0;
}

::deep .thread-reply .message-content {
    font-size: 0.85rem;
}

